import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import galleryService from '../services/galleryService';
import '../styles/Pages.css';
import { toast } from 'react-toastify';

const EventGallery = () => {
  const { eventId } = useParams();
  const [gallery, setGallery] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const [uploadingImage, setUploadingImage] = useState(false);

  useEffect(() => {
    fetchGallery();
  }, [eventId]);

  const fetchGallery = async () => {
    setLoading(true);
    try {
      const data = await galleryService.getGalleryByEvent(eventId);
      setGallery(data);
    } catch (error) {
      toast.error('Failed to fetch gallery');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadingImage(true);
    try {
      const formData = new FormData();
      formData.append('image', file);
      formData.append('event', eventId);

      await galleryService.uploadPhoto(eventId, formData);
      toast.success('Photo uploaded successfully!');
      fetchGallery();
    } catch (error) {
      toast.error('Failed to upload photo');
    } finally {
      setUploadingImage(false);
    }
  };

  const handleDeletePhoto = async (photoId) => {
    if (window.confirm('Are you sure you want to delete this photo?')) {
      try {
        await galleryService.deletePhoto(photoId);
        toast.success('Photo deleted successfully!');
        fetchGallery();
      } catch (error) {
        toast.error('Failed to delete photo');
      }
    }
  };

  return (
    <div className="event-gallery-page">
      <div className="page-header">
        <h1>Event Photo Gallery</h1>
        <p>View and share event memories</p>
      </div>

      <div className="gallery-upload">
        <label htmlFor="file-upload" className="upload-btn">
          {uploadingImage ? 'Uploading...' : 'Upload Photo'}
        </label>
        <input
          id="file-upload"
          type="file"
          accept="image/*"
          onChange={handleFileUpload}
          disabled={uploadingImage}
          style={{ display: 'none' }}
        />
      </div>

      {loading ? (
        <div className="loading">Loading gallery...</div>
      ) : gallery.length > 0 ? (
        <div className="gallery-container">
          <div className="gallery-grid">
            {gallery.map(photo => (
              <div key={photo._id} className="gallery-item">
                <img
                  src={photo.image}
                  alt={photo.caption}
                  onClick={() => setSelectedImage(photo)}
                  className="gallery-thumbnail"
                />
                <div className="gallery-overlay">
                  <button
                    className="btn-delete"
                    onClick={() => handleDeletePhoto(photo._id)}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>

          {selectedImage && (
            <div className="lightbox" onClick={() => setSelectedImage(null)}>
              <div className="lightbox-content" onClick={(e) => e.stopPropagation()}>
                <button 
                  className="close-btn"
                  onClick={() => setSelectedImage(null)}
                >
                  ×
                </button>
                <img src={selectedImage.image} alt={selectedImage.caption} />
                {selectedImage.caption && (
                  <p className="lightbox-caption">{selectedImage.caption}</p>
                )}
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="no-events">
          <p>No photos in gallery yet</p>
        </div>
      )}
    </div>
  );
};

export default EventGallery;
